/**
 * Button sounds with fixed meanings (public/audio/clicks, generated by Scripts/make_click_sounds.py):
 *   - the bottom navigation bar always plays `nav`
 *   - buttons on a screen play that tab's own sound (today, mealPlan, log, foods, workout, progress, coach);
 *     sheets opened from a tab use the same sound
 *   - first-run setup plays `onboarding`
 * Mirrors MyCoach/Core/DesignSystem/ButtonSounds.swift.
 *
 * Uses Web Audio for low latency. Sounds are decoded on the first tap (browsers require a user gesture).
 */
import type { MainTab } from "../state/store";

export type ButtonSound = "nav" | MainTab | "onboarding";

export const BUTTON_SOUNDS: ButtonSound[] = [
  "nav",
  "today",
  "mealPlan",
  "log",
  "foods",
  "workout",
  "progress",
  "coach",
  "onboarding",
];

/** Longer celebration effects (public/audio/effects, generated by Scripts/make_effect_sounds.py). */
export type EffectSound = "celebration" | "whoosh" | "fire";
export const EFFECT_SOUNDS: EffectSound[] = ["celebration", "whoosh", "fire"];

const VOLUME = 0.55;
const EFFECT_VOLUME = 0.85;
const TAPPABLE =
  'button:not(:disabled), [role="button"], a[href], label.toggle, label.list-row:has(input[type="checkbox"]), summary';

let enabled = true;
/** Where the user is: the active tab, or onboarding. Set by App. */
let context: ButtonSound = "today";
let ctx: AudioContext | undefined;
let gain: GainNode | undefined;
const buffers = new Map<ButtonSound | EffectSound, AudioBuffer>();
let loading: Promise<void> | undefined;

function ensureAudio(): AudioContext | undefined {
  if (!ctx) {
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return undefined;
    ctx = new Ctor();
    gain = ctx.createGain();
    gain.gain.value = VOLUME;
    gain.connect(ctx.destination);
  }
  if (ctx.state === "suspended") ctx.resume().catch(() => {});
  loading ??= Promise.all(
    [
      ...BUTTON_SOUNDS.map((name) => [name, `./audio/clicks/${name}.wav`] as const),
      ...EFFECT_SOUNDS.map((name) => [name, `./audio/effects/${name}.wav`] as const),
    ].map(([name, url]) =>
      fetch(url)
        .then((r) => r.arrayBuffer())
        .then((b) => ctx!.decodeAudioData(b))
        .then((buf) => void buffers.set(name, buf))
        .catch(() => undefined),
    ),
  ).then(() => undefined);
  return ctx;
}

/** Which sound a tap should make: nav bar → `nav`; anything else → the current screen's sound. */
export function soundForTap(inNavBar: boolean, current: ButtonSound): ButtonSound {
  return inNavBar ? "nav" : current;
}

export function playSound(name: ButtonSound) {
  if (!enabled) return;
  const ac = ensureAudio();
  const buffer = buffers.get(name);
  if (!ac || !gain || !buffer) return;
  const src = ac.createBufferSource();
  src.buffer = buffer;
  src.connect(gain);
  src.start();
}

/** Plays a celebration effect (respects the same Settings toggle as button sounds). */
const lastEffectAt = new Map<EffectSound, number>();
export function playEffect(name: EffectSound) {
  if (!enabled) return;
  // Ignore an immediate repeat (e.g. React StrictMode re-running an effect).
  const now = Date.now();
  if (now - (lastEffectAt.get(name) ?? 0) < 250) return;
  lastEffectAt.set(name, now);
  const ac = ensureAudio();
  if (!ac) return;
  const start = () => {
    const buffer = buffers.get(name);
    if (!buffer) return;
    const g = ac.createGain();
    g.gain.value = EFFECT_VOLUME;
    g.connect(ac.destination);
    const src = ac.createBufferSource();
    src.buffer = buffer;
    src.connect(g);
    src.start();
  };
  if (buffers.has(name)) start();
  else void loading?.then(start);
}

export function setClickSoundsEnabled(on: boolean) {
  enabled = on;
}

export function setSoundContext(next: ButtonSound) {
  context = next;
}

if (typeof document !== "undefined") {
  document.addEventListener(
    "pointerdown",
    (e) => {
      if (!enabled) return;
      const target = e.target as Element | null;
      const tappable = target?.closest?.(TAPPABLE);
      if (tappable) playSound(soundForTap(!!tappable.closest(".tabbar"), context));
      else ensureAudio(); // warm up on any first touch so the next tap is instant
    },
    { capture: true, passive: true },
  );
}
